import React from 'react';
import { NavLink, Outlet, useNavigate } from 'react-router-dom';
import './Layout.css';
import { useAuth } from '../context/AuthContext';

export default function Layout() {
  const navigate = useNavigate();
  const { user, logout } = useAuth();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <div className="app-shell">
      <aside className="sidebar">
        <div className="sidebar-top">
          <div className="brand">
            <span>🩺</span>
            <div>
              <strong>Medical Agenda</strong>
              <small>Sistema clínico</small>
            </div>
          </div>
        </div>

        <nav className="sidebar-nav">
          <NavLink to="/dashboard">Dashboard</NavLink>
          <NavLink to="/calendar">Calendario</NavLink>
          {user?.role === 'medico' && <NavLink to="/my-calendar">Mi calendario</NavLink>}
          <NavLink to="/appointments">Citas</NavLink>

          {/* Pacientes: visible para admin y profesionales (solo búsqueda para profesionales) */}
          {(user?.role === 'admin' || user?.role === 'medico') && (
            <NavLink to="/patients">Pacientes</NavLink>
          )}

          {/* Profesionales solo para admin */}
          {user?.role === 'admin' && <NavLink to="/professionals">Profesionales</NavLink>}

          {/* Evolución clínica disponible para profesionales y admin */}
          {(user?.role === 'admin' || user?.role === 'medico') && (
            <NavLink to="/evolution">Evolución Clínica</NavLink>
          )}

          {/* Pagos: profesional ve solo sus pagos, admin ve todo */}
          {(user?.role === 'admin' || user?.role === 'medico') && (
            <NavLink to="/payments">Pagos</NavLink>
          )}

          {/* Reportes y mensajería para admin */}
          {user?.role === 'admin' && <NavLink to="/reports">Reportes</NavLink>}
          {user?.role === 'admin' && <NavLink to="/treatments">Tratamientos</NavLink>}
          {user?.role === 'admin' && <NavLink to="/categories">Categorías</NavLink>}
          {(user?.role === 'admin' || user?.role === 'medico') && <NavLink to="/messages">Mensajería</NavLink>}

          {/* Configuración solo admin */}
          {user?.role === 'admin' && <NavLink to="/configuration">Configuración</NavLink>}
        </nav>

        <div className="sidebar-footer">
          <div className="sidebar-user">
            <span>{user?.firstName ? `${user.firstName.charAt(0)}${user.lastName?.charAt(0)}` : '--'}</span>
            <div>
              <strong>{user?.firstName || 'Usuario'}</strong>
              <small>{user?.role || 'Invitado'}</small>
            </div>
          </div>
          <button className="logout-btn" onClick={handleLogout}>Cerrar sesión</button>
        </div>
      </aside>

      <div className="content-wrapper">
        <header className="topbar">
          <div className="topbar-left">
            <h1>Medical Agenda</h1>
          </div>
          <div className="topbar-right">
            <button className="topbar-action" onClick={() => navigate('/dashboard')}>Inicio</button>
          </div>
        </header>
        <main className="content-main">
          <Outlet />
        </main>
      </div>
    </div>
  );
}
